        if not seq:
            return 0
        comp = [0] * m
        for j in seq:
            p = matrix[j]
            start = [0] * m
            start[0] = p[0]
            for k in range(1, m):
                start[k] = max(comp[k], start[k-1]) + p[k]
            comp = start
        return comp[-1]
    if n == 1:
        return {'job_sequence': [1]}
    s = jobs[:2]
    ms1 = makespan(s)
    ms2 = makespan(s[::-1])
    if ms1 <= ms2:
        current = s
    else:
